    private function limitedVehicle(array $d): ?array {if(empty($d['vehicle_id']))return null;$v=$this->one('vehicles',['id'=>$d['vehicle_id']]);if(!$v)return null;return array_intersect_key($v,array_flip(['id','category_id','brand','model','plate']));}
