        if(in_array((int)$local->format('N'),$cfg['peak_weekdays']??[1,2,3,4,5],true))foreach(($cfg['peak_hours']??[[7,9],[17,20]])as$window)if($minutes>=(int)$window[0]*60&&$minutes<(int)$window[1]*60)$peak=true;
