        $b=['fuel'=>$fuel,'base'=>(string)$c['base_price'],'distance'=>MongoValidation::round(bcmul($distance,(string)$c['price_per_km'],12)),'weight'=>MongoValidation::round(bcmul($w,(string)$c['weight_price'],12)),'volume'=>MongoValidation::round(bcmul($volume,(string)$c['volume_price'],12)),'operational'=>(string)$c['operational_fee'],'protection'=>$protection?(string)$c['protection_fee']:'0.00','extras'=>bcmul((string)$extras,(string)$cfg['extra_service_fee'],2),'tolls'=>$tolls,'distance_source'=>'manual_estimate','tariffs'=>'fictitious_configurable'];
