    private function hasDocument(string $user,string $kind,bool $verified=false,?string $vehicle=null): bool {$f=['user_id'=>$user,'kind'=>$kind,'status'=>$verified?'verified':['$ne'=>'rejected']];if($vehicle!==null)$f['vehicle_id']=$vehicle;return(bool)$this->one('documents',$f);}
