    private function monthlyRevenue(array $a): array {
        $this->assertAdmin();$year=MongoValidation::integer($a['p_year']??null,2000,2100);
        $tz=new \DateTimeZone('America/Sao_Paulo');
        $start=new \DateTimeImmutable(sprintf('%04d-01-01T00:00:00',$year),$tz);
        $end=$start->modify('+1 year');$zero=new Decimal128('0.00');
        $known=['$and'=>[['$ne'=>[['$ifNull'=>['$commission_amount',null]],null]],['$ne'=>[['$ifNull'=>['$commission_percent',null]],null]]]];
        $estimated=['$or'=>[['$eq'=>[['$ifNull'=>['$confirmation_time_estimated',false]],true]],['$eq'=>[['$ifNull'=>['$confirmed_at',null]],null]]]];
        $pipeline=[
            ['$addFields'=>[
                '_recognized_at'=>['$dateFromString'=>['dateString'=>['$ifNull'=>['$confirmed_at',['$ifNull'=>['$updated_at','$created_at']]]],'onError'=>null,'onNull'=>null]],
                '_has_commission'=>$known,'_time_estimated'=>$estimated
