            ['$match'=>['_recognized_at'=>['$gte'=>new \MongoDB\BSON\UTCDateTime($start),'$lt'=>new \MongoDB\BSON\UTCDateTime($end)]]],
            ['$facet'=>[
                'monthly'=>[
                    ['$match'=>['status'=>'confirmed','is_demo'=>false]],
                    ['$group'=>[
                        '_id'=>['$month'=>['date'=>'$_recognized_at','timezone'=>'America/Sao_Paulo']],
                        'gross_amount'=>['$sum'=>'$amount'],
                        'commission_amount'=>['$sum'=>['$cond'=>['$_has_commission','$commission_amount',$zero]]],
                        'driver_amount'=>['$sum'=>['$cond'=>['$_has_commission',['$subtract'=>['$amount','$commission_amount']],$zero]]],
                        'payment_count'=>['$sum'=>1],
                        'commission_payment_count'=>['$sum'=>['$cond'=>['$_has_commission',1,0]]],
                        'unconfigured_payment_count'=>['$sum'=>['$cond'=>['$_has_commission',0,1]]],
                        'legacy_confirmation_count'=>['$sum'=>['$cond'=>['$_time_estimated',1,0]]]
                    ]]
                ],
                'demo'=>[['$match'=>['status'=>'confirmed','is_demo'=>true]],['$count'=>'n']],
                'refunded'=>[['$match'=>['status'=>'refunded','is_demo'=>false]],['$count'=>'n']]
            ]]
        ];
        $cmd=new Command(['aggregate'=>'payments','pipeline'=>$pipeline,'cursor'=>new \stdClass(),'allowDiskUse'=>true]);
        $cursor=$this->manager->executeCommand($this->database,$cmd,$this->transaction?['session'=>$this->transaction]:[]);
        $cursor->setTypeMap(['root'=>'array','document'=>'array','array'=>'array']);$aggregated=$cursor->toArray()[0]??[];
        $byMonth=[];foreach(($aggregated['monthly']??[])as$row)$byMonth[(int)$row['_id']]=$row;
        $r=['year'=>$year,'currency'=>'BRL','timezone'=>'America/Sao_Paulo','basis'=>'confirmed_company_commission',
            'commission_percent'=>$this->pricingSettings()['commission_percent'],'months'=>[],
            'total_gross_amount'=>'0.00','total_commission_amount'=>'0.00','total_driver_amount'=>'0.00',
            'total_payment_count'=>0,'total_commission_payment_count'=>0,'unconfigured_payment_count'=>0,'legacy_confirmation_count'=>0,
            'demo_excluded_count'=>(int)($aggregated['demo'][0]['n']??0),'refunded_excluded_count'=>(int)($aggregated['refunded'][0]['n']??0)];
        for($m=1;$m<=12;$m++){
            $row=$byMonth[$m]??[];$month=['month'=>$m,'month_start'=>sprintf('%04d-%02d-01',$year,$m)];
            foreach(['gross_amount','commission_amount','driver_amount']as$key){$month[$key]=bcadd((string)($row[$key]??'0'),'0',2);$r['total_'.$key]=bcadd($r['total_'.$key],$month[$key],2);}
            foreach(['payment_count','commission_payment_count','unconfigured_payment_count']as$key)$month[$key]=(int)($row[$key]??0);
            $r['total_payment_count']+=$month['payment_count'];$r['total_commission_payment_count']+=$month['commission_payment_count'];
            $r['unconfigured_payment_count']+=$month['unconfigured_payment_count'];$r['legacy_confirmation_count']+=(int)($row['legacy_confirmation_count']??0);$r['months'][]=$month;
        }
        return$r;
    }
